package com.portfolio.features.integration.github;
import com.portfolio.features.integration.github.entity.*; import com.portfolio.features.integration.github.repository.*; import com.portfolio.features.integration.github.client.GitHubApiClient; import com.portfolio.features.integration.github.security.TokenEncryptionException; import com.portfolio.features.integration.github.security.TokenEncryptionService; import com.portfolio.features.portfolio.service.PortfolioAccessService; import com.portfolio.features.project.entity.*; import com.portfolio.features.project.repository.ProjectRepository; import com.portfolio.features.user.entity.AppUser; import java.net.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import lombok.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.client.RestClient;
@Service @RequiredArgsConstructor public class GitHubIntegrationService { private final GitHubConnectionRepository connections; private final GitHubOAuthStateRepository states; private final GitHubApiClient github; private final ProjectRepository projects; private final PortfolioAccessService portfolios; private final TokenEncryptionService encryption; private final RestClient http=RestClient.create(); @Value("${app.github.client-id:}") String clientId; @Value("${app.github.client-secret:}") String clientSecret; @Value("${app.github.redirect-uri:}") String redirectUri; @Value("${app.github.frontend-url:http://localhost:3000}") String frontendUrl;
 @Transactional public String connect(AppUser user){if(clientId.isBlank()||clientSecret.isBlank()||redirectUri.isBlank()||!encryption.isConfigured())throw new IllegalArgumentException("GitHub integration is not configured.");String raw=UUID.randomUUID()+"-"+UUID.randomUUID();GitHubOAuthState s=new GitHubOAuthState();s.setUser(user);s.setStateHash(hash(raw));s.setExpiresAt(LocalDateTime.now().plusMinutes(10));states.save(s);return "https://github.com/login/oauth/authorize?client_id="+encode(clientId)+"&redirect_uri="+encode(redirectUri)+"&scope=read:user&state="+encode(raw);}
 @Transactional public String callback(String code,String state){try{var oauth=states.findByStateHash(hash(state)).filter(s->!s.isUsed()&&s.getExpiresAt().isAfter(LocalDateTime.now())).orElseThrow(()->new IllegalArgumentException("GitHub authorization has expired. Please try again."));oauth.setUsed(true);var token=http.post().uri("https://github.com/login/oauth/access_token").accept(MediaType.APPLICATION_JSON).body(Map.of("client_id",clientId,"client_secret",clientSecret,"code",code,"redirect_uri",redirectUri)).retrieve().body(Token.class);if(token==null||token.access_token()==null)throw new IllegalArgumentException("Unable to connect GitHub.");var user=http.get().uri("https://api.github.com/user").header("Authorization","Bearer "+token.access_token()).header("Accept","application/vnd.github+json").retrieve().body(GitHubUser.class);if(user==null)throw new IllegalArgumentException("Unable to retrieve GitHub account.");var c=connections.findByUserId(oauth.getUser().getId()).orElseGet(GitHubConnection::new);c.setUser(oauth.getUser());c.setGithubUserId(user.id());c.setGithubUsername(user.login());c.setGithubAvatarUrl(user.avatar_url());c.setEncryptedAccessToken(encryption.encrypt(token.access_token()));c.setScope(token.scope());connections.save(c);return frontendUrl+"/dashboard/builder?github=connected";}catch(Exception e){return frontendUrl+"/dashboard/builder?github=error";}}
 @Transactional(readOnly=true) public Status status(AppUser user){return connections.findByUserId(user.getId()).map(c->new Status(true,c.getGithubUsername(),c.getGithubAvatarUrl())).orElse(new Status(false,null,null));} @Transactional public void disconnect(AppUser user){connections.findByUserId(user.getId()).ifPresent(connections::delete);} private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} private String encode(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);} public record Status(boolean connected,String username,String avatarUrl){} record Token(String access_token,String scope){} record GitHubUser(long id,String login,String avatar_url){}
 @Transactional(readOnly=true) public RepositoryPage repositories(AppUser user,int page,int size){var c=connection(user);var p=portfolios.mine(user);var list=github.repos(token(c),Math.max(1,page),Math.min(100,Math.max(1,size))).stream().map(r->new RepositoryResponse(r.id(),r.name(),r.full_name(),r.description(),r.html_url(),r.homepage(),r.language(),r.stargazers_count(),r.forks_count(),r.private_(),r.fork(),r.archived(),r.updated_at(),projects.existsByPortfolioIdAndGithubRepositoryId(p.getId(),r.id()))).toList();return new RepositoryPage(list,page,size,list.size()==size);}
 public ImportResult importRepositories(AppUser user,List<Long> ids){var results=new ArrayList<ImportItem>();for(Long id:ids)try{results.add(importOne(user,id));}catch(Exception e){results.add(new ImportItem(id,"FAILED",null,"Unable to import repository."));}long imported=results.stream().filter(x->x.status().equals("IMPORTED")).count(),skipped=results.stream().filter(x->x.status().equals("SKIPPED")).count();return new ImportResult(imported,skipped,results.size()-imported-skipped,results);}
 @Transactional public ImportItem importOne(AppUser user,Long id){var c=connection(user);String token=token(c);var portfolio=portfolios.mine(user);if(projects.existsByPortfolioIdAndGithubRepositoryId(portfolio.getId(),id))return new ImportItem(id,"SKIPPED",null,"Repository already imported.");var r=github.repo(token,id);if(r.private_()||r.archived())throw new IllegalArgumentException("Repository cannot be imported.");Project p=new Project();p.setPortfolio(portfolio);p.setTitle(r.name());p.setSlug(slug(r.name(),portfolio.getId()));p.setShortDescription(r.description());p.setDescription(r.description());p.setGithubUrl(r.html_url());p.setDemoUrl(r.homepage());p.setGithubRepositoryId(r.id());p.setSource("GITHUB");var languages=github.languages(token,r.full_name().split("/")[0],r.name());int order=0;for(String language:languages.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(5).map(Map.Entry::getKey).toList()){var t=new ProjectTechnology();t.setProject(p);t.setTechnology(language);t.setSortOrder(order++);p.getTechnologies().add(t);}projects.save(p);return new ImportItem(id,"IMPORTED",p.getId(),null);}
 private GitHubConnection connection(AppUser u){return connections.findByUserId(u.getId()).orElseThrow(()->new IllegalArgumentException("GitHub account is not connected."));} private String token(GitHubConnection connection){try{return encryption.decrypt(connection.getEncryptedAccessToken());}catch(TokenEncryptionException exception){throw new IllegalArgumentException("GitHub connection is invalid. Please reconnect GitHub.");}} private String slug(String raw,UUID portfolio){String base=raw.toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");String value=base;int n=2;while(projects.existsByPortfolioIdAndSlug(portfolio,value))value=base+"-"+n++;return value;} public record RepositoryResponse(long githubId,String name,String fullName,String description,String repositoryUrl,String homepage,String primaryLanguage,int stars,int forks,boolean privateRepository,boolean fork,boolean archived,OffsetDateTime updatedAt,boolean alreadyImported){} public record RepositoryPage(List<RepositoryResponse> items,int page,int size,boolean hasMore){} public record ImportRequest(List<Long> repositoryIds){} public record ImportItem(Long githubId,String status,UUID projectId,String message){} public record ImportResult(long imported,long skipped,long failed,List<ImportItem> results){}
}
